--
-- Name: charge_windows_valid(text[]); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.charge_windows_valid(p_windows text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
    SELECT cardinality(p_windows) <= 4
       AND NOT EXISTS (
           SELECT 1 FROM unnest(p_windows) AS w
           WHERE w !~ '^([01][0-9]|2[0-3]):[0-5][0-9]-([01][0-9]|2[0-3]):[0-5][0-9]$'
              OR split_part(w, '-', 1) = split_part(w, '-', 2)
       );
$_$;

--
-- Name: ensure_telemetry_partitions(integer); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.ensure_telemetry_partitions(days_ahead integer DEFAULT 7) RETURNS integer
    LANGUAGE sql
    AS $$
    SELECT og.lifecycle_ensure_daily_partitions('telemetry', 1, days_ahead)
$$;

--
-- Name: hub_mark_serviced(text, timestamp with time zone); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.hub_mark_serviced(p_hub_id text, p_at timestamp with time zone) RETURNS void
    LANGUAGE sql
    AS $$
    UPDATE og.hub SET last_serviced_at = GREATEST(COALESCE(last_serviced_at, p_at), p_at)
    WHERE hub_id = p_hub_id;
$$;

--
-- Name: hub_serviced_by_asset_event(); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.hub_serviced_by_asset_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.event_type IN ('INVERTER_REPLACED', 'RECOMMISSIONED') THEN
        PERFORM og.hub_mark_serviced(NEW.hub_id, NEW.occurred_at);
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: hub_serviced_by_calibration(); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.hub_serviced_by_calibration() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.outcome IN ('IMPROVED', 'CORRECTED', 'NO_CHANGE') AND NEW.verified_at IS NOT NULL THEN
        PERFORM og.hub_mark_serviced(NEW.hub_id, NEW.verified_at);
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: hub_serviced_by_work_order(); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.hub_serviced_by_work_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'CLOSED' AND NEW.closed_at IS NOT NULL THEN
        PERFORM og.hub_mark_serviced(NEW.hub_id, NEW.closed_at);
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: hub_units_default(); Type: FUNCTION; Schema: og; Owner: -
--

CREATE FUNCTION og.hub_units_default() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.units = 1 AND NEW.e_kwh >= 70 THEN
        NEW.units := 2;
    END IF;
    RETURN NEW;
END
$$;

