--
-- Name: lifecycle_partitions; Type: VIEW; Schema: og; Owner: -
--

CREATE VIEW og.lifecycle_partitions AS
 SELECT (p.relname)::text AS parent,
    (c.relname)::text AS partition,
    (b.expr = 'DEFAULT'::text) AS is_default,
        CASE
            WHEN ((r.m[1] IS NULL) OR (r.m[1] = 'MINVALUE'::text)) THEN NULL::timestamp with time zone
            ELSE (r.m[1])::timestamp with time zone
        END AS lower_ts,
        CASE
            WHEN ((r.m[2] IS NULL) OR (r.m[2] = 'MAXVALUE'::text)) THEN NULL::timestamp with time zone
            ELSE (r.m[2])::timestamp with time zone
        END AS upper_ts,
    pg_total_relation_size((c.oid)::regclass) AS total_bytes,
    (GREATEST(c.reltuples, (0)::real))::bigint AS est_rows
   FROM (((((pg_inherits i
     JOIN pg_class c ON ((c.oid = i.inhrelid)))
     JOIN pg_class p ON (((p.oid = i.inhparent) AND (p.relkind = 'p'::"char"))))
     JOIN pg_namespace n ON (((n.oid = p.relnamespace) AND (n.nspname = 'og'::name))))
     CROSS JOIN LATERAL ( SELECT pg_get_expr(c.relpartbound, c.oid) AS expr) b)
     CROSS JOIN LATERAL ( SELECT regexp_match(b.expr, 'FROM \(''?([^'')]*)''?\) TO \(''?([^'')]*)''?\)'::text) AS m) r(m));

